/*
`E_q` = `$λ_{q,1}$`||`$q_g$`-`$q_h$`+t`$m_g$`||^2 + `$λ_{q,1}$`||`$q_h$`-`$q_g$`+t`$m_h$`||^2 + `$λ_{q,2}$`||`$\angle$`(`$m_g$`,`$m_h$`)||^2 
where
`$q_g$` ∈ ℝ^n : point
`$q_h$` ∈ ℝ^n : point
`$m_g$` ∈ ℝ^n : the material vectors of $g$
`$m_h$` ∈ ℝ^n : the material vectors at $h$
`$\angle$` ∈ ℝ^n, ℝ^n -> ℝ^n
`$λ_{q,1}$` ∈ ℝ : the constraint weights for the position
`$λ_{q,2}$` ∈ ℝ : the constraint weights for the direction
t ∈ ℝ

*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    DT E_q;

    heartlib(
        const Eigen::VectorXd & q_g,
        const Eigen::VectorXd & q_h,
        const Eigen::VectorXd & m_g,
        const Eigen::VectorXd & m_h,
        const std::function<Eigen::VectorXd(Eigen::VectorXd, Eigen::VectorXd)> & angle,
        const double & λ_q_comma_1,
        const double & λ_q_comma_2,
        const double & t)
    {
        const long n = q_g.size();
        assert( q_h.size() == n );
        assert( m_g.size() == n );
        assert( m_h.size() == n );
        // `E_q` = `$λ_{q,1}$`||`$q_g$`-`$q_h$`+t`$m_g$`||^2 + `$λ_{q,1}$`||`$q_h$`-`$q_g$`+t`$m_h$`||^2 + `$λ_{q,2}$`||`$\angle$`(`$m_g$`,`$m_h$`)||^2
        E_q = λ_q_comma_1 * pow((q_g - q_h + t * m_g).template lpNorm<2>(), 2) + λ_q_comma_1 * pow((q_h - q_g + t * m_h).template lpNorm<2>(), 2) + λ_q_comma_2 * pow((angle((m_g).eval(), (m_h).eval())).template lpNorm<2>(), 2);
    }
};

